// HasUsageRecords applies the HasEdge predicate on the "usageRecords" edge.
func HasUsageRecords() predicate.McpService {
	return predicate.McpService(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, UsageRecordsTable, UsageRecordsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasUsageRecordsWith applies the HasEdge predicate on the "usageRecords" edge with a given conditions (other predicates).
func HasUsageRecordsWith(preds ...predicate.McpUsage) predicate.McpService {
	return predicate.McpService(func(s *sql.Selector) {
		step := newUsageRecordsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.McpService) predicate.McpService {
	return predicate.McpService(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.McpService) predicate.McpService {
	return predicate.McpService(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.McpService) predicate.McpService {
	return predicate.McpService(sql.NotPredicates(p))
}
